"기함 <b>「{0}」</b>은(는) 돌아오지 못했습니다. 싣고 있던 화물도 함께 사라졌습니다.<br>\n      구조선이 승무원들을 고향 <b>지구</b>로 데려왔습니다.<br>\n      남은 함선 <b>{1}척</b> 가운데 <b>「{2}」</b>이(가) 새 기함이 됩니다{3}.<br>\n      <b>승무원·크레딧·연구·발견 기록은 그대로입니다.</b>":"旗艦<b>「{0}」</b>は戻ってきませんでした。積んでいた貨物も一緒に失われました。<br>\n      救助船がクルーたちを故郷の<b>地球</b>へ連れ帰りました。<br>\n      残った艦船<b>{1}隻</b>のうち、<b>「{2}」</b>が新たな旗艦になります{3}。<br>\n      <b>クルー・クレジット・研究・発見記録はそのままです。</b>",
