"지구를 떠난 지 <b>{0}일</b>.<br>\n    당신의 함선은 마침내 시간과 공간이 시작된 한 점에 닿았습니다.<br>\n    발견한 천체 <b>{1}/{2}</b> · 전투 승리 <b>{3}</b>회 ·\n    함께한 승무원 <b>{4}</b>명<br><br>\n    모든 별과 은하, 그리고 우리 자신이 바로 이 빛에서 태어났습니다.<br>\n    <b>항해는 끝나지 않습니다.</b> 아직 발견하지 못한 우주가 기다립니다.":"地球を離れて<b>{0}日</b>。<br>\n    あなたの艦船はついに、時間と空間が始まった一点にたどり着きました。<br>\n    発見した天体 <b>{1}/{2}</b> · 戦闘勝利 <b>{3}</b>回 ·\n    共に旅したクルー <b>{4}</b>人<br><br>\n    すべての星と銀河、そして私たち自身が、まさにこの光から生まれました。<br>\n    <b>航海は終わりません。</b>まだ見ぬ宇宙が待っています。",
