"전진익과 측면 함포를 갖춘 주력 전투함. 해적들이 가장 마주치기 싫어하는 배.":"前進翼と舷側砲を備えた主力戦闘艦。海賊がいちばん出くわしたくない船。",
"컨테이너 네 열을 싣는 초대형 화물선. 희귀 등급 최고의 적재량을 자랑한다.":"コンテナを4列積める超大型貨物船。レア級最高の積載量を誇る。",
