"모두 말없이 유성우를 바라봤습니다. 함교 분위기가 한결 따뜻해졌습니다. (호감도 +4) 💞":"誰もが黙って流星群を見つめました。ブリッジの空気がぐっと温かくなりました。(好感度 +4) 💞",
"⛏ 유성 조각을 건진다 (크레딧 · 선체 위험)":"⛏ 流星のかけらを拾う (クレジット · 船体に危険)",
